<script setup lang="ts">
import { computed, inject, ref, defineAsyncComponent } from "vue";
import type { OfficeReferenceSnapshot } from "@/api/types";
import { workspaceFileNavigationKey } from "@/agent/workspaceFileNavigation";
import { officeReferenceTarget } from "@/agent/officeReferenceNavigation";
import { Icon } from "@iconify/vue";
import { fileIcon } from "./fileIcons";
const props = defineProps<{ office: OfficeReferenceSnapshot; detailsOnly?: boolean }>();
const InformationEntryDialog = defineAsyncComponent(() => import("./InformationEntryDialog.vue"));
const informationOpen = ref(false);
const information = computed(() => props.office.information);
const informationAvailable = computed(() => !!information.value && /^inf_[a-f0-9]{32}$/.test(information.value.entry_id) && Number.isSafeInteger(information.value.version) && information.value.version > 0 && /^[a-f0-9]{64}$/.test(information.value.snapshot_sha256));
const navigation = inject(workspaceFileNavigationKey, null);
const scope = computed(() => { const value = navigation?.scope(); return value && (!props.office.source_session || props.office.source_session === value.conversationId) ? value : null; });
const target = computed(() => scope.value ? officeReferenceTarget(props.office, scope.value) : null);
function open() { if (informationAvailable.value) { informationOpen.value = true; return; } const origin = scope.value; if (origin && navigation && target.value) navigation.open(target.value, origin); }
</script>
<template><div v-if="detailsOnly" class="office-snapshot"><strong>{{ office.title }}</strong><small>{{ [office.sheet, office.range].filter(Boolean).join(' · ') }} · {{ informationAvailable ? $t('informationOffice.savedOrigin', { n: information!.version }) : office.canvas_version }}<template v-if="office.dirty"> · {{ $t('nestedShortcuts.unsaved') }}</template></small><pre>{{ office.text }}</pre><button type="button" :disabled="!target && !informationAvailable" @click="open">{{ informationAvailable ? $t('informationOffice.openSavedOrigin') : $t(target ? 'nestedShortcuts.openSource' : 'nestedShortcuts.noFileAccess') }}</button></div><el-popover v-else trigger="click" :width="'min(520px, calc(100vw - 32px))'" placement="top-start" popper-class="office-reference-popover"><template #reference><button type="button" class="office-reference" data-reference-kind="office" :title="office.path"><Icon :icon="fileIcon(office.title)" /><span>{{ [office.title, office.sheet, office.range].filter(Boolean).join(' · ') }}</span></button></template><div class="office-snapshot"><strong>{{ office.title }}</strong><small>{{ [office.sheet, office.range].filter(Boolean).join(' · ') }} · {{ informationAvailable ? $t('informationOffice.savedOrigin', { n: information!.version }) : office.canvas_version }}<template v-if="office.dirty"> · {{ $t('nestedShortcuts.unsaved') }}</template></small><pre>{{ office.text }}</pre><button type="button" :disabled="!target && !informationAvailable" @click="open">{{ informationAvailable ? $t('informationOffice.openSavedOrigin') : $t(target ? 'nestedShortcuts.openSource' : 'nestedShortcuts.noFileAccess') }}</button></div></el-popover><InformationEntryDialog v-if="informationAvailable && informationOpen" :model-value="informationOpen" :entry-id="information!.entry_id" :version="information!.version" @update:model-value="informationOpen = $event" /></template>
<style scoped>.office-reference { display:inline-flex; align-items:center; gap:5px; max-width:min(100%,300px); margin:1px 3px; padding:1px 7px; border:1px solid var(--el-border-color-light); border-radius:7px; background:var(--el-fill-color-light); color:var(--el-text-color-primary); font:inherit; font-size:.9em; line-height:1.65; cursor:pointer; vertical-align:baseline; }.office-reference svg{width:15px;height:15px;flex:none}.office-reference span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.office-snapshot{display:flex;flex-direction:column;gap:10px;min-width:0}.office-snapshot strong,.office-snapshot small{overflow-wrap:anywhere}.office-snapshot small{color:var(--el-text-color-secondary)}pre{margin:0;max-height:320px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;user-select:text;font:12px/1.65 var(--el-font-family-monospace,monospace)}button{align-self:flex-start}</style>
